import{u as p,k as r,aj as u,O as s,l as e,cD as o,T as d,ae as k,c as m,E as h,cE as b,cF as x,cG as y}from"./vendor.af032cc6.js";const g={tr:{title:"Dok\xFCmantasyon",intro:"Alexen panelinin t\xFCm b\xF6l\xFCmleri ve REST API kullan\u0131m\u0131. Bir konuyu soldaki i\xE7indekilerden se\xE7ebilir ya da sayfada gezinebilirsin.",sections:[{id:"roller",title:"Roller ve izinler",blocks:[{p:"\xDC\xE7 rol vard\u0131r: creator (sunucunun sahibi), sudo y\xF6neticiler ve bayiler (reseller)."},{ul:["Creator: her \u015Feyi yapabilir; lisans ve tehlikeli/kald\u0131rma i\u015Flemleri yaln\u0131zca creator'a \xF6zeldir. Creator ve kullan\u0131c\u0131lar\u0131 sudo'lardan gizlidir.","Sudo: creator ile ayn\u0131 yetkilere sahiptir (lisans ve uninstall hari\xE7); di\u011Fer sudo'lar\u0131 da y\xF6netebilir.","Bayi (admin): kendi kullan\u0131c\u0131lar\u0131n\u0131 y\xF6netir; kullan\u0131c\u0131 say\u0131s\u0131/trafik kotas\u0131 ve host-gruplar\u0131 ile s\u0131n\u0131rlan\u0131r."]},{h:"Bayi izinleri (sudo/creator a\xE7ar-kapat\u0131r)"},{ul:["Config kopyalayabilir: kapal\u0131yken bayi kullan\u0131c\u0131lar\u0131n config (kod) linklerini kopyalayamaz \u2014 ama abonelik (sub) adresini yine kopyalayabilir.","IP/cihaz limitini de\u011Fi\u015Ftirebilir: kapal\u0131yken limitler salt-okunur olur ve bayi bir kullan\u0131c\u0131n\u0131n cihaz\u0131n\u0131/IP'sini silemez, engelini kald\u0131ramaz."]},{p:"Bayi listesinde her bayinin ka\xE7 kullan\u0131c\u0131 a\xE7t\u0131\u011F\u0131/sildi\u011Fi g\xF6sterilir."}]},{id:"kullanicilar",title:"Kullan\u0131c\u0131lar",blocks:[{p:"Kullan\u0131c\u0131 olu\u015Ftururken protokolleri, biti\u015F tarihini, veri limitini ve iste\u011Fe ba\u011Fl\u0131 IP/cihaz limitini belirlersin."},{ul:["IP limiti: ayn\u0131 anda ba\u011Fl\u0131 IP say\u0131s\u0131n\u0131 s\u0131n\u0131rlar; fazlas\u0131, \xF6ncekilerden biri d\xFC\u015Fene kadar engellenir.","Cihaz (HWID) limiti: aboneli\u011Fi ka\xE7 cihaz\u0131n kullanabilece\u011Fini s\u0131n\u0131rlar; cihazlar kullan\u0131c\u0131 baz\u0131nda y\xF6netilir.","Her kullan\u0131c\u0131 i\xE7in engellenen yeni IP ve reddedilen yeni cihaz say\u0131lar\u0131 kullan\u0131c\u0131 penceresinde g\xF6r\xFCn\xFCr.","Online IP'ler: kimin, hangi node ve inbound \xFCzerinden ba\u011Fl\u0131 oldu\u011Funu canl\u0131 g\xF6r\xFCrs\xFCn; bir IP'yi tek t\u0131kla d\xFC\u015F\xFCrebilirsin."]}]},{id:"abonelik",title:"Abonelik ve sub sayfas\u0131",blocks:[{p:"Her kullan\u0131c\u0131n\u0131n bir abonelik (sub) linki vard\u0131r. Abonelik sayfas\u0131n\u0131n ba\u015F\u0131na, kullan\u0131c\u0131n\u0131n durumuna g\xF6re (varsay\u0131lan, s\xFCresi dolmu\u015F, limitli, devre d\u0131\u015F\u0131, yak\u0131nda dolacak) bir mesaj \u015Fablonu koyabilirsin."},{p:"\u015Eablonlarda y\xF6nergeler ve yer tutucular kullan\u0131l\u0131r. Y\xF6nerge sat\u0131rlar\u0131 ayn\u0131 zamanda HTTP ba\u015Fl\u0131\u011F\u0131 olur:"},{code:`#profile-title: \u015Eirketim
#announce: Merhaba {username}
Limit: {used} / {limit} \xB7 Kalan: {remaining}
#support-url: https://siten.com/destek?t={token}`},{p:"Kullan\u0131labilir yer tutucular:"},{ul:["{username} {used} {limit} {remaining} {expiretime} {days} {status}","{token}: kullan\u0131c\u0131n\u0131n kendi abonelik token'\u0131 \u2014 kendi destek linkinde kullan\u0131c\u0131y\u0131 tan\u0131mlamak i\xE7in idealdir."]},{p:"Y\xF6nergenin ba\u015F\u0131na base64: yazarsan de\u011Fer base64 olarak kodlan\u0131r. Domain ayarlar\u0131ndan abonelik linkinin domain, path ve son ekini \xF6zelle\u015Ftirebilirsin."}]},{id:"sunucular",title:"Node'lar, host'lar ve gruplar",blocks:[{ul:["Node: trafi\u011Fi ta\u015F\u0131yan uzak sunucular; panelden kurulur/y\xF6netilir.","Host'lar: her inbound i\xE7in istemcilere verilecek adres/port/\u015Fablon ayarlar\u0131.","Host gruplar\u0131: bir bayinin yaln\u0131zca izin verdi\u011Fin host'lar\u0131 da\u011F\u0131tmas\u0131n\u0131 sa\u011Flar.","Core ve outbound ayarlar\u0131, preroute (t\xFCnelleme) ve otomatik-de\u011Fi\u015Fim de node b\xF6l\xFCm\xFCndedir."]}]},{id:"diger",title:"External config, etkinlik, yedek ve g\xFCncelleme",blocks:[{ul:["External config: her abonelik linkinin alt\u0131na eklenen ek config'ler; yedek URL'ler, rastgele URL ve protokol filtresi desteklenir. Bayi baz\u0131nda da ayarlanabilir.","Etkinlik g\xFCnl\xFC\u011F\xFC: her giri\u015F ve her de\u011Fi\u015Fiklik (kim, ne zaman, hangi cihaz/IP). T\xFCr (\xF6r. 'ba\u015Far\u0131s\u0131z giri\u015F'), kullan\u0131c\u0131 veya IP ile aranabilir.","Yedek ve g\xFCncelleme: panelden yedek al\u0131p geri y\xFCkleyebilir, yeni s\xFCr\xFCme g\xFCncelleyebilirsin (g\xFCncelleme \xF6nce yedek al\u0131r, ba\u015Far\u0131s\u0131z olursa eskiye d\xF6ner)."]}]},{id:"api",title:"REST API",blocks:[{p:"Panel tam bir REST API sunar. \xC7o\u011Fu u\xE7 bir bearer token ister. \xD6nce giri\u015F yap\u0131p token al, sonra Authorization ba\u015Fl\u0131\u011F\u0131nda g\xF6nder:"},{code:`curl -X POST https://PANELINIZ/api/admin/token \\
     -d 'username=<admin>&password=<sifre>'
# -> {"access_token": "...", "token_type": "bearer"}

curl https://PANELINIZ/api/users \\
     -H 'Authorization: Bearer <access_token>'`},{p:"/sub/... alt\u0131ndaki abonelik u\xE7lar\u0131 herkese a\xE7\u0131kt\u0131r ve URL'deki token ile do\u011Frulan\u0131r."},{p:"Tam u\xE7 listesi ve makine-okur \u015Fema GitHub deposundad\u0131r: docs/API.md ve docs/openapi.json (Postman/Insomnia veya Redoc'a aktarabilirsin). \u0130nteraktif Swagger aray\xFCz\xFCn\xFC a\xE7mak i\xE7in paneli DOCS=True ile ba\u015Flat\u0131n (/docs ve /redoc)."}]}]},en:{title:"Documentation",intro:"A complete guide to every part of the Alexen panel plus REST API usage. Pick a topic from the table of contents or scroll through.",sections:[{id:"roles",title:"Roles & permissions",blocks:[{p:"There are three roles: creator (the server owner), sudo admins, and resellers (admins)."},{ul:["Creator: can do everything; license and dangerous/uninstall actions are creator-only. The creator and its users are hidden from sudo admins.","Sudo: same powers as the creator (except license and uninstall); can also manage other sudo admins.","Reseller (admin): manages its own users; bounded by a user-count/traffic quota and host groups."]},{h:"Reseller permissions (toggled by a sudo/creator)"},{ul:["Can copy configs: when off, the reseller cannot copy users' config links \u2014 but can still copy the subscription (sub) link.","Can edit IP/device limits: when off, the limits are read-only and the reseller cannot delete a user's devices/IPs or unblock them."]},{p:"The admins list shows how many users each reseller created/deleted."}]},{id:"users",title:"Users",blocks:[{p:"When creating a user you set the protocols, expiry, data limit, and optional IP/device limits."},{ul:["IP limit: caps simultaneously connected IPs; extra ones are blocked until an earlier one disconnects.","Device (HWID) limit: caps how many devices can use a subscription; devices are managed per user.","Each user shows how many new IPs were blocked and new devices rejected.","Online IPs: see who is connected, on which node and inbound, in real time; kick one IP with a click."]}]},{id:"subscription",title:"Subscription & sub page",blocks:[{p:"Every user has a subscription (sub) link. You can prepend a message template to the sub page per user state (default, expired, limited, disabled, near-expire)."},{p:"Templates use directives and placeholders; directive lines also become HTTP headers:"},{code:`#profile-title: My Company
#announce: Hello {username}
Limit: {used} / {limit} \xB7 Left: {remaining}
#support-url: https://yoursite.com/help?t={token}`},{p:"Available placeholders:"},{ul:["{username} {used} {limit} {remaining} {expiretime} {days} {status}","{token}: the user's own subscription token \u2014 ideal for identifying the user inside your own support link."]},{p:"Prefix a directive value with base64: to base64-encode it. Customize the sub link's domain, path and suffix from Domain settings."}]},{id:"servers",title:"Nodes, hosts & groups",blocks:[{ul:["Node: the remote servers that carry traffic; installed/managed from the panel.","Hosts: the address/port/template clients are given for each inbound.","Host groups: let a reseller hand out only the hosts you allow.","Core & outbound settings, preroute (tunneling) and auto-change also live under the node area."]}]},{id:"other",title:"External configs, activity, backup & update",blocks:[{ul:["External configs: extra configs appended to each link subscription; fallback URLs, a random URL and a protocol filter are supported. Can be set per reseller too.","Activity log: every sign-in and change (who, when, which device/IP). Search by type (e.g. 'failed login'), user or IP.","Backup & update: back up and restore from the panel, and update to a new version (it backs up first and rolls back if an update fails)."]}]},{id:"api",title:"REST API",blocks:[{p:"The panel exposes a full REST API. Most endpoints need a bearer token: log in, then send it in the Authorization header:"},{code:`curl -X POST https://YOUR-PANEL/api/admin/token \\
     -d 'username=<admin>&password=<password>'
# -> {"access_token": "...", "token_type": "bearer"}

curl https://YOUR-PANEL/api/users \\
     -H 'Authorization: Bearer <access_token>'`},{p:"Subscription endpoints under /sub/... are public and authenticated by the token in the URL."},{p:"The full endpoint list and machine-readable schema live in the GitHub repo: docs/API.md and docs/openapi.json (import into Postman/Insomnia or Redoc). To enable the interactive Swagger UI, start the panel with DOCS=True (/docs and /redoc)."}]}]}},F=({block:i})=>"h"in i?e(o,{size:"sm",mt:3,mb:1,children:i.h}):"p"in i?e(d,{fontSize:"sm",color:"gray.600",_dark:{color:"gray.300"},lineHeight:"tall",children:i.p}):"ul"in i?e(b,{spacing:1.5,pl:2,children:i.ul.map((l,n)=>e(x,{fontSize:"sm",color:"gray.600",_dark:{color:"gray.300"},lineHeight:"tall",children:l},n))}):e(y,{display:"block",whiteSpace:"pre-wrap",p:3,borderRadius:"10px",fontSize:"xs",w:"full",overflowX:"auto",children:i.code}),v=()=>{const{i18n:i}=p(),l=(i.language||"en").slice(0,2),n=g[l==="tr"?"tr":"en"];return r(u,{align:"stretch",spacing:5,maxW:"900px",children:[r(s,{children:[e(o,{size:"lg",mb:1,children:n.title}),e(d,{fontSize:"sm",color:"gray.500",children:n.intro})]}),e(s,{className:"alexen-page",borderWidth:"1px",borderRadius:"16px",p:4,children:e(u,{align:"stretch",spacing:1,children:n.sections.map((a,t)=>r(k,{href:`#${a.id}`,fontSize:"sm",color:"primary.500",fontWeight:"medium",children:[t+1,". ",a.title]},a.id))})}),n.sections.map(a=>r(s,{id:a.id,className:"alexen-page",borderWidth:"1px",borderRadius:"16px",p:5,scrollMarginTop:"80px",children:[e(o,{size:"md",mb:3,children:a.title}),e(u,{align:"stretch",spacing:2.5,children:a.blocks.map((t,c)=>e(m.exports.Fragment,{children:e(F,{block:t})},c))})]},a.id)),r(d,{fontSize:"xs",color:"gray.500",textAlign:"center",children:[e(h,{colorScheme:"primary",variant:"subtle",mr:2,children:"Alexen"}),"github.com/Alexander-official/alexen-panel \xB7 docs/API.md"]})]})};export{v as DocumentationPage,v as default};
